        Regex("(\\d+) / (\\d+) reels") to {m:MatchResult->"${m.groupValues[1]} / ${m.groupValues[2]} রিলস"},

        Regex("remaining of (\\d+)") to {m:MatchResult->"${m.groupValues[1]}টির মধ্যে বাকি"},
        Regex("or (\\d+) reels left") to {m:MatchResult->"অথবা ${m.groupValues[1]}টি রিলস বাকি"},
        Regex("(\\d+) reels") to {m:MatchResult->"${m.groupValues[1]}টি রিলস"},
        Regex("(\\d+) reels today") to {m:MatchResult->"আজ ${m.groupValues[1]}টি রিলস"},
        Regex("Selected \\((\\d+)\\)") to {m:MatchResult->"নির্বাচিত (${m.groupValues[1]})"},
        Regex("(\\d+) days with records") to {m:MatchResult->"${m.groupValues[1]} দিনের হিসাব"},
        Regex("(\\d+) watched · (\\d+) allowed today") to {m:MatchResult->"আজ ${m.groupValues[1]}টি দেখা · সীমা ${m.groupValues[2]}টি"}
    )
    fun translate(text:String,language:String):String {
        if(language!="bn")return text
        bn[text]?.let{return it}
        UiCopyDetails.bn[text]?.let{return it}
        SettingsCopy.bn[text]?.let{return it}
        dynamic.forEach{(pattern,replace)->pattern.matchEntire(text)?.let{return replace(it)}}
        return text
    }
}
